 n,l,st,ct=cv2.connectedComponentsWithStats(m)
 print('\\n',name,np.count_nonzero(m))
 for i in sorted(range(1,n),key=lambda z:st[z,4],reverse=True)[:10]:
  x,y,w,h,a=st[i];
  if a>10: print(a,(x,y,w,h),ct[i])
# print extrema saturation upper, chunks
for y in range(0,500,25):
 for x in range(0,1280,25):
  roi=hsv[y:y+25,x:x+25]
  sat=np.mean(roi[:,:,1]); val=np.mean(roi[:,:,2]);
  if sat>80 and val>50: print('patch',x,y,round(sat),round(val),np.median(roi[:,:,0]))
